export function isPlainObject(value) {
  if (value === null || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

export function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      defineKey(out, key, clone(value[key]));
    }
    return out;
  }
  return value;
}

function defineKey(obj, key, value) {
  Object.defineProperty(obj, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
}

export function deepMerge(base, override) {
  if (!isPlainObject(base)) base = {};
  if (!isPlainObject(override)) return clone(base);
  const out = clone(base);
  for (const key of Object.keys(override)) {
    const value = override[key];
    if (value === null) {
      delete out[key];
    } else if (isPlainObject(value)) {
      const existing = Object.prototype.hasOwnProperty.call(out, key) ? out[key] : undefined;
      defineKey(out, key, deepMerge(isPlainObject(existing) ? existing : {}, value));
    } else {
      defineKey(out, key, clone(value));
    }
  }
  return out;
}
EOF
cat > env.mjs <<'EOF'
import { clone, isPlainObject } from "./merge.mjs";

const PREFIX = "APP_";

function has(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function findKey(obj, part) {
  const lower = part.toLowerCase();
  if (has(obj, part)) return part;
  return Object.keys(obj).find((k) => k.toLowerCase() === lower);
}

function convert(raw, existing) {
  if (typeof existing === "number") {
    const n = Number(raw);
    if (Number.isNaN(n)) throw new TypeError(`Invalid number: ${raw}`);
    return n;
  }
  if (typeof existing === "boolean") {
    if (raw === "true") return true;
    if (raw === "false") return false;
    throw new TypeError(`Invalid boolean: ${raw}`);
  }
  if (Array.isArray(existing)) {
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch {
      throw new TypeError(`Invalid JSON array: ${raw}`);
    }
    if (!Array.isArray(parsed)) throw new TypeError(`Not a JSON array: ${raw}`);
    return parsed;
  }
  return raw;
}

function set(obj, key, value) {
  Object.defineProperty(obj, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
}

export function applyEnv(config, processEnv = {}) {
  const result = clone(config);
  for (const name of Object.keys(processEnv)) {
    if (!name.startsWith(PREFIX) || name.length === PREFIX.length) continue;
    const raw = processEnv[name];
    if (raw === undefined) continue;
    const parts = name.slice(PREFIX.length).split("__");
    let node = result;
    for (let i = 0; i < parts.length; i++) {
      const found = findKey(node, parts[i]);
      const key = found ?? parts[i].toLowerCase();
      if (i === parts.length - 1) {
        set(node, key, convert(String(raw), found === undefined ? undefined : node[key]));
      } else {
        if (found === undefined || !isPlainObject(node[key])) set(node, key, {});
        node = node[key];
      }
    }
  }
  return result;
}
EOF
