import { readFileSync } from "node:fs";
import { join } from "node:path";
import { deepMerge } from "./merge.mjs";
import { applyEnv } from "./env.mjs";

function readJson(file, optional) {
  let text;
  try {
    text = readFileSync(file, "utf8");
  } catch (err) {
    if (optional && err.code === "ENOENT") return {};
    throw err;
  }
  return JSON.parse(text);
}

export function loadConfig(dir, env = "development", processEnv = {}) {
  const base = readJson(join(dir, "default.json"), false);
  const specific = readJson(join(dir, `${env}.json`), true);
  return applyEnv(deepMerge(base, specific), processEnv);
}
EOF
